from fastapi import APIRouter, FastAPI
from fastapi.exceptions import FastAPIError

def test_circular_include():
    router_a = APIRouter()
    router_b = APIRouter()

    @router_a.get("/a")
    def a():
        return {"msg": "a"}

    @router_b.get("/b")
    def b():
        return {"msg": "b"}

    print("Including B into A...")
    router_a.include_router(router_b)
    print(f"Router A routes count: {len(router_a.routes)}") # Should be 2

    print("Including A into B...")
    router_b.include_router(router_a)
    print(f"Router B routes count: {len(router_b.routes)}") # Should be 1 + 2 = 3

    print("Success: No infinite loop")

if __name__ == "__main__":
    test_circular_include()

